package br.com.minhagibiteca.catalog.presentation;
import br.com.minhagibiteca.auth.application.CurrentAuthenticatedUser; import br.com.minhagibiteca.catalog.application.*; import br.com.minhagibiteca.catalog.domain.Edition; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class EditionController { private final EditionService editions; private final PublisherService publishers; private final ComicSeriesService series; private final CurrentAuthenticatedUser user; public EditionController(EditionService e,PublisherService p,ComicSeriesService s,CurrentAuthenticatedUser u){editions=e;publishers=p;series=s;user=u;}
 @GetMapping("/edicoes") String list(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,Model m){m.addAttribute("editions",editions.list(user.id(),q,PageRequest.of(Math.max(0,page),20,Sort.by("normalizedTitle"))));m.addAttribute("query",q);return "edicoes/list";}
 @GetMapping("/edicoes/nova") String n(Model m){m.addAttribute("editionForm",new EditionForm());return form(m,"Nova edição","/edicoes");}
 @PostMapping("/edicoes") String c(@Valid @ModelAttribute("editionForm")EditionForm f,BindingResult r,Model m,RedirectAttributes a){if(r.hasErrors())return form(m,"Nova edição","/edicoes");editions.create(user.id(),cmd(f));a.addFlashAttribute("successMessage","Edição cadastrada com sucesso.");return "redirect:/edicoes";}
 @GetMapping("/edicoes/{id}") String detail(@PathVariable UUID id,Model m){m.addAttribute("edition",editions.findOwned(id,user.id()));return "edicoes/detail";}
 @GetMapping("/edicoes/{id}/editar") String e(@PathVariable UUID id,Model m){Edition x=editions.findOwned(id,user.id()); EditionForm f=new EditionForm();f.setPublisherId(x.getPublisherId());f.setSeriesId(x.getSeriesId());f.setTitle(x.getTitle());f.setEditorialNumber(x.getEditorialNumber());f.setVariant(x.getVariant());f.setIsbn(x.getIsbn());f.setPublicationYear(x.getPublicationYear());f.setFormat(x.getFormat());f.setNotes(x.getNotes());m.addAttribute("editionForm",f);return form(m,"Editar edição","/edicoes/"+id+"/editar");}
 @PostMapping("/edicoes/{id}/editar") String u(@PathVariable UUID id,@Valid @ModelAttribute("editionForm")EditionForm f,BindingResult r,Model m,RedirectAttributes a){if(r.hasErrors())return form(m,"Editar edição","/edicoes/"+id+"/editar");editions.update(id,user.id(),cmd(f));a.addFlashAttribute("successMessage","Edição atualizada com sucesso.");return "redirect:/edicoes/"+id;}
 @PostMapping("/edicoes/{id}/excluir") String d(@PathVariable UUID id,RedirectAttributes a){editions.delete(id,user.id());a.addFlashAttribute("successMessage","Edição excluída com sucesso.");return "redirect:/edicoes";}
 private String form(Model m,String title,String action){m.addAttribute("pageTitle",title);m.addAttribute("formAction",action);m.addAttribute("publishers",publishers.options(user.id()));m.addAttribute("seriesPage",series.list(user.id(),"",PageRequest.of(0,200,Sort.by("normalizedName"))));return "edicoes/form";}
 private EditionService.Command cmd(EditionForm f){return new EditionService.Command(f.getPublisherId(),f.getSeriesId(),f.getTitle(),f.getEditorialNumber(),f.getVariant(),f.getIsbn(),f.getPublicationYear(),f.getFormat(),f.getNotes());}}
